/* @lc app=leetcode id=3999 lang=kotlin */ class Solution { fun mr(s: String): String = s.length.let { n -> generateSequence(Triple(0, 1, 0)) { (i, j, k) -> if (i < n && j < n && k < n) (s[(i + k) % n] - s[(j + k) % n]).let { df -> if (df == 0) Triple(i, j, k + 1) else if (df > 0) (i + k + 1).let { ni -> Triple(if (ni == j) ni + 1 else ni, j, 0) } else (j + k + 1).let { nj -> Triple(i, if (nj == i) nj + 1 else nj, 0) } } else null }.last().let { (i, j, _) -> minOf(i, j).let { r -> s.substring(r) + s.substring(0, r) } } } fun minimumGroups(words: Array<String>): Int = words.map { w -> mr(w.filterIndexed { i, _ -> i % 2 == 0 }) + "|" + mr(w.filterIndexed { i, _ -> i % 2 == 1 }) }.toSet().size }